+                    tokens.stream().mapToInt(Integer::valueOf).toArray(),
+                    docCountProvider.getDocCount(doc)
+                );
+                long newSize = categorizer.ramBytesUsed();
+                if (newSize - previousSize > 0) {
+                    addRequestCircuitBreakerBytes(newSize - previousSize);
+                }
