+            name,
+            factories,
+            context,
+            parent,
+            indexedFieldName,
+            fieldType,
+            bucketCountThresholds,
+            maxUniqueTokens,
+            maxMatchTokens,
+            similarityThreshold,
+            categorizationAnalyzerConfig,
+            metadata
+        );
