+        assertArrayEquals(
+            innerTreeNode.getCategorization(getTokens(bytesRefHash, "footiny", "bar", "baz", "biz")).getCategorization(),
+            getTokens(bytesRefHash, "*", "bar", "baz", "biz")
+        );
+    }
